import{_ as s,l as i,o as e,c as n,v as t,p as l,x as o,d,i as A,S as c}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"虚索引物理标记 VIPT","description":"","frontmatter":{"title":"虚索引物理标记 VIPT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vipt-cache.md","filePath":"cs/vipt-cache.md","lastUpdated":1789023840000}'),p={name:"cs/vipt-cache.md"};function B(P,a,h,T,E,_){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="虚索引物理标记-vipt" tabindex="-1">虚索引物理标记 VIPT <a class="header-anchor" href="#虚索引物理标记-vipt" aria-label="Permalink to &quot;虚索引物理标记 VIPT&quot;">​</a></h1><div class="epigraph"><p>用虚拟地址的页内偏移去索引 L1，可以和 TLB 并行；标签必须用物理页号比，否则同义别名会把同一行存两份。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Patterson and Hennessy, COD 整理</footer></div><p><a href="/cs/rrip-dead-block">上一课</a> 假定「已经找到那一组」。L1 命中要进流水线的关键路径：<a href="/cs/tlb-translate">TLB</a> 若必须先做完才能索引 cache，就多一级延迟。本课不重讲 RRPV。缺口是<strong>VIPT：页内位移做索引，物理标签做匹配</strong>，以及它何时仍然安全。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PIPT（物理索引物理标签）最干净，但索引依赖 PA，必须等 TLB。VIVT（虚拟索引虚拟标签）最快，但上下文切换要冲刷或加 ASID，且别名严重。缺口是折中：<strong>索引只用 VA 的页内部分（VA 与 PA 相同），标签用 PA</strong>，于是 TLB 与 cache 数据阵列并行。</p><p>约束：组索引位必须落在页内偏移里，否则不同虚页可能索引到不同组却对应同一物理行——那是下一课别名。于是 L1 容量、路数、行大小被页大小卡住：例如 4KiB 页、64B 行，索引最多 6 位，直接映射最多 4KiB；要 32KiB 就至少 8 路。</p><p><span class="marginnote">这就是为何许多核的 L1D 是 32KiB 8 路而不是 64KiB 2 路：VIPT 要在 4KiB 页下保持索引落在页内。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>load：VA 同时送 TLB 与 L1 索引。数据阵列读出该组所有路的数据与物理标签；TLB 给出 PPN 后与各路标签比较，命中选路。缺失按 PA 填入，标签写 PPN。</p>',9)),(e(),l(c,null,{default:o(()=>[A(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20IDX%5B%22%E9%A1%B5%E5%86%85%E4%BD%8D%E7%A7%BB%E7%B4%A2%E5%BC%95%20L1%22%5D%0A%20%20VA%20--%3E%20TLB%5B%22TLB%20%E5%87%BA%20PPN%22%5D%0A%20%20IDX%20--%3E%20TAG%5B%22%E5%90%84%E8%B7%AF%E7%89%A9%E7%90%86%E6%A0%87%E7%AD%BE%22%5D%0A%20%20TLB%20--%3E%20CMP%5B%22PPN%20%E4%B8%8E%E6%A0%87%E7%AD%BE%E6%AF%94%E8%BE%83%22%5D%0A%20%20TAG%20--%3E%20CMP%0A%20%20CMP%20--%3E%20HIT%5B%22%E9%80%89%E4%B8%AD%E4%B8%80%E8%B7%AF%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>命中延迟：TLB 与 SRAM 并行，比较在关键路径后段。操作系统改映射必须让 TLB 与 L1 一致：shootdown 时对应行要无效，否则物理标签会指着错误页。这与 <a href="/cs/tlb-shootdown">tlb-shootdown</a> 衔接，本课只要求 L1 的标签是物理的，不会跨进程「碰巧 VA 相同就命中」。</p><p>L2 通常 PIPT，容量不受页大小限制，因为可以等 L1 缺失后再用 PA 访问。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理「索引超出页内」时的反别名硬件，下一课。也不把软件保证（页着色）提前讲完。大页会放宽 VIPT 的容量限制，那是后课大页与 TLB。</p><p>后课默认：L1 常用 VIPT，索引限于页内位移。一旦索引用到 VPN 位，同义别名必须显式处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VIPT 让 L1 与 TLB 并行，标签仍是物理的。</li><li>索引必须落在页内，否则容量与路数被页大小锁死。</li><li>超出页内的索引引出下一课缓存别名。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const V=s(p,[["render",B]]);export{L as __pageData,V as default};
